(()=>{"use strict";const TYPE="aitogy/gnss-fixed-position";function validate(coords){if(!coords||["lat","lon","alt"].some(key=>typeof coords[key]!="number"||!Number.isFinite(coords[key]))||Math.abs(coords.lat)>90||Math.abs(coords.lon)>180)throw new Error("Tọa độ sao chép thiếu hoặc không hợp lệ. Cần đủ vĩ độ, kinh độ và độ cao h.");return{lat:coords.lat,lon:coords.lon,alt:coords.alt}}window.CorsCoordinateClipboard={encode(coords){return JSON.stringify({type:TYPE,version:1,crs:"EPSG:4979",height_type:"ellipsoidal",coords:validate(coords)})},parse(text){let packet;try{packet=JSON.parse(text)}catch(_){return null}if((packet==null?void 0:packet.type)!==TYPE)return null;if(packet.version!==1||packet.crs!=="EPSG:4979"||packet.height_type!=="ellipsoidal")throw new Error("Dữ liệu dán chưa phải WGS 84 với độ cao h. Hãy dùng “Sao chép cho GNSS” trong công cụ chuyển tọa độ.");return validate(packet.coords)}}})();
